import { defineElement, type UsaElement } from '../base';
import { clampN, ownChildren, part, dropParts } from './shared';
import css from './carousel.css?raw';

/**
 * `<usa-carousel>` (6.2) — swipeable carousel / slider. Each child is a slide.
 * Attributes: `effect` (`slide` · `fade` · `scale` · `cards` — 3D coverflow),
 * `autoplay` (ms; pauses on hover, focus, when off screen and under reduced
 * motion), `loop`, `index`, `label` ("Carousel"), `no-controls`, `no-dots`.
 * Drag / swipe with a pointer, arrow keys when focused. API: `next()`,
 * `prev()`, `goTo(i)`, `index`, `length`. Events: `usa:change` (`{ index, from }`).
 * Reduced motion: slides switch without movement.
 */
export interface UsaCarouselElement extends UsaElement {
  index: number;
  readonly length: number;
  next(): void;
  prev(): void;
  goTo(i: number): void;
}

export const CAROUSEL_EFFECTS = ['slide', 'fade', 'scale', 'cards'] as const;

export function defineCarousel(tag = 'usa-carousel'): CustomElementConstructor | undefined {
  return defineElement(
    tag,
    (Base) => {
      class UsaCarousel extends Base {
        static get observedAttributes(): string[] {
          return ['effect', 'autoplay', 'loop', 'no-controls', 'no-dots', 'label', 'index'];
        }
        private _i = 0;
        private _slides: HTMLElement[] = [];
        private _track: HTMLElement | null = null;
        private _timer = 0;
        private _hold = false;
        private _dots: HTMLButtonElement[] = [];

        get length(): number {
          return this._slides.length;
        }
        get index(): number {
          return this._i;
        }
        set index(v: number) {
          this.goTo(v);
        }
        get effect(): string {
          const e = this.str('effect', 'slide');
          return (CAROUSEL_EFFECTS as readonly string[]).includes(e) ? e : 'slide';
        }

        mount(): void {
          this.dataset.effect = this.effect; // (not the observed attribute: no re-mount loop)
          this.toggleAttribute('data-reduced', this.reduced);
          const old = this.querySelector<HTMLElement>(':scope > .usa-carousel-viewport');
          this._slides = old ? ownChildren(old.firstElementChild as HTMLElement) : ownChildren(this);
          dropParts(this);
          const vp = part('div', 'usa-carousel-viewport', { 'aria-live': this.num('autoplay', 0) ? 'off' : 'polite' });
          const track = part('div', 'usa-carousel-track');
          this._track = track;
          vp.append(track);
          const n = this._slides.length;
          this._slides.forEach((s, i) => {
            s.setAttribute('role', 'group');
            s.setAttribute('aria-roledescription', 'slide');
            s.setAttribute('aria-label', `${i + 1} of ${n}`);
            track.append(s);
          });
          this.prepend(vp);
          this.setAttribute('role', 'region');
          this.setAttribute('aria-roledescription', 'carousel');
          this.setAttribute('aria-label', this.str('label', 'Carousel'));
          if (!this.hasAttribute('tabindex')) this.tabIndex = 0;
          if (n > 1 && !this.flag('no-controls')) {
            const prev = part('button', 'usa-carousel-nav usa-carousel-prev', { type: 'button', 'aria-label': 'Previous slide' }, '‹');
            const next = part('button', 'usa-carousel-nav usa-carousel-next', { type: 'button', 'aria-label': 'Next slide' }, '›');
            this.listen(prev, 'click', () => this.prev());
            this.listen(next, 'click', () => this.next());
            this.append(prev, next);
          }
          this._dots = [];
          if (n > 1 && !this.flag('no-dots')) {
            const dots = part('div', 'usa-carousel-dots', { role: 'group', 'aria-label': 'Choose slide' });
            for (let i = 0; i < n; i++) {
              const d = part('button', 'usa-carousel-dot', { type: 'button', 'aria-label': `Slide ${i + 1}` });
              this.listen(d, 'click', () => this.goTo(i));
              this._dots.push(d);
              dots.append(d);
            }
            this.append(dots);
          }
          this._i = clampN(Math.round(this.num('index', 0)), 0, Math.max(0, n - 1));
          this.layout(0);
          this.listen(this, 'keydown', (e: KeyboardEvent) => {
            if (e.key === 'ArrowRight') (e.preventDefault(), this.next());
            else if (e.key === 'ArrowLeft') (e.preventDefault(), this.prev());
          });
          this.drag(vp);
          const ms = this.num('autoplay', 0);
          if (ms > 0 && n > 1 && !this.reduced) {
            let visible = true;
            this.inView((v) => (visible = v));
            const pause = (on: boolean) => () => (this._hold = on);
            this.listen(this, 'pointerenter', pause(true));
            this.listen(this, 'pointerleave', pause(false));
            this.listen(this, 'focusin', pause(true));
            this.listen(this, 'focusout', pause(false));
            this._timer = window.setInterval(() => {
              if (visible && !this._hold && !document.hidden) this.next();
            }, Math.max(1200, ms));
            this.onCleanup(() => clearInterval(this._timer));
          }
        }

        private drag(vp: HTMLElement): void {
          let x0 = 0;
          let dx = 0;
          let id = -1;
          this.listen(vp, 'pointerdown', (e: PointerEvent) => {
            if (this.length < 2 || (e.target as Element).closest('button,a,input')) return;
            id = e.pointerId;
            x0 = e.clientX;
            dx = 0;
            this.setAttribute('data-dragging', '');
          });
          this.listen(window, 'pointermove', (e: PointerEvent) => {
            if (e.pointerId !== id) return;
            dx = e.clientX - x0;
            this.layout(dx / Math.max(1, vp.clientWidth));
          });
          const end = (e: PointerEvent) => {
            if (e.pointerId !== id) return;
            id = -1;
            this.removeAttribute('data-dragging');
            const w = Math.max(1, vp.clientWidth);
            if (Math.abs(dx) > w * 0.18) dx < 0 ? this.next() : this.prev();
            else this.layout(0);
          };
          this.listen(window, 'pointerup', end);
          this.listen(window, 'pointercancel', end);
        }

        /** Position the slides (`drag` = fraction of a slide the pointer moved). */
        private layout(drag: number): void {
          const n = this.length;
          const i = this._i;
          const fx = this.effect;
          if (this._track) this._track.style.transform = fx === 'slide' ? `translateX(${(-i + drag) * 100}%)` : '';
          this._slides.forEach((s, k) => {
            let off = k - i + drag;
            if (this.flag('loop') && n > 2) {
              if (off > n / 2) off -= n;
              if (off < -n / 2) off += n;
            }
            const active = k === i;
            s.toggleAttribute('data-active', active);
            s.setAttribute('aria-hidden', String(!active));
            s.inert = !active;
            if (fx === 'slide') {
              s.style.transform = s.style.opacity = s.style.zIndex = s.style.filter = '';
              return;
            }
            const a = Math.abs(off);
            if (fx === 'fade') {
              s.style.opacity = String(clampN(1 - a, 0, 1));
              s.style.transform = '';
            } else if (fx === 'scale') {
              s.style.opacity = String(clampN(1 - a, 0, 1));
              s.style.transform = `scale(${1 + Math.min(1, a) * (off < 0 ? 0.12 : -0.12)})`;
            } else {
              s.style.opacity = a > 2.2 ? '0' : String(1 - Math.min(a, 2) * 0.28);
              s.style.transform = `translateX(${off * 58}%) translateZ(${-a * 140}px) rotateY(${clampN(-off * 38, -60, 60)}deg)`;
              s.style.filter = a > 0.5 ? `brightness(${1 - Math.min(a, 2) * 0.18})` : '';
            }
            s.style.zIndex = String(100 - Math.round(a * 10));
          });
          this._dots.forEach((d, k) => d.setAttribute('aria-current', String(k === i)));
        }

        goTo(to: number): void {
          const n = this.length;
          if (!n) return;
          const t = this.flag('loop') ? ((Math.round(to) % n) + n) % n : clampN(Math.round(to), 0, n - 1);
          const from = this._i;
          this._i = t;
          this.layout(0);
          if (t !== from) this.emit('change', { index: t, from });
        }
        next(): void {
          this.goTo(this._i + 1 >= this.length && !this.flag('loop') ? 0 : this._i + 1);
        }
        prev(): void {
          this.goTo(this._i - 1 < 0 && !this.flag('loop') ? this.length - 1 : this._i - 1);
        }
      }
      return UsaCarousel as unknown as CustomElementConstructor;
    },
    { id: 'carousel', text: css }
  );
}
